const createHttpError = (statusCode, message) => {
  const error = new Error(message);
  error.statusCode = statusCode;
  return error;
};

const escapeRegexValue = (value) => String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const getActiveAccessInvitation = async (token) => {
  const trimmedToken =
    typeof token === 'string' ? token.trim() : token != null ? String(token).trim() : '';

  if (!trimmedToken) {
    return null;
  }

  const invitation = await AccessInvitation.findOne({ token: trimmedToken }).exec();

  if (!invitation) {
    throw createHttpError(httpStatus.NOT_FOUND, 'Invitation not found');
  }

  if (invitation.expiresAt && invitation.expiresAt < new Date()) {
    throw createHttpError(httpStatus.GONE, 'Invitation has expired');
  }

  if (invitation.isUsed && !invitation.multiUse) {
    throw createHttpError(httpStatus.CONFLICT, 'Invitation already used');
  }

  if (typeof invitation.role !== 'string' || !invitation.role.trim()) {
    throw createHttpError(httpStatus.BAD_REQUEST, 'Invitation role is invalid');
  }

  if (
    typeof invitation.access !== 'object' ||
    invitation.access === null ||
    Array.isArray(invitation.access)
  ) {
    throw createHttpError(httpStatus.BAD_REQUEST, 'Invitation access is invalid');
  }

  const business = await Business.findOne({
    BID: {
      $regex: `^${escapeRegexValue(invitation.bid)}$`,
      $options: 'i',
    },
  })
    .select('business_name BID')
    .lean()
    .exec();

  if (!business) {
    throw createHttpError(httpStatus.NOT_FOUND, 'Invitation business not found');
  }

  return {
    token: trimmedToken,
    invitation,
    business,
  };
};

