const generateUniqueUid = async (baseUid) => {
  let suffix = 1;
  let uniqueUid = baseUid;
  let exists = true;
  //console.log({baseUid, suffix});
  while (exists) {
    // Append the suffix to the base UID
    let candidateUid = baseUid;
    if (suffix - 1 != 0) {
      candidateUid += (suffix - 1).toString();
    }

    exists = !(await isUniqueUid(candidateUid));
    console.log({ exists });
    if (exists) {
      suffix++;
    } else {
      uniqueUid = candidateUid;
    }
  }

  return { uniqueUid, suffix };
};

