              : 'approved',
          verification_message: user?.reject_reason ? user.reject_reason : verificationMessage,
          verification_expired: verificationExpired || false,
          verification_expiry_date: user.verification_status ? verifExpiryDate : '',
        };

        const payment_status = await paymentStatus.findOne({
          contact: user.contact,
        });

        if (!payment_status && user.payment_status == 'Paid') {
          data.payment_status = 'PREMIUM PAID';
        } else if (payment_status) {
          if (payment_status.frequency == 'MONTH') {
            data.payment_status = 'PREMIUM PAID';
          } else if (payment_status.frequency == 'YEAR') {
            data.payment_status = 'NORMAL PAID';
          }
        }

        if (user.UID[0] == 'L' && user.UID[1] == 'U' && user.UID[2] == 'I' && user.UID[3] == 'D') {
          data.level = 0;
        } else if (user.UID[0] == 'T' && user.UID[1] == 'U' && user.UID[2] == 'I' && user.UID[3] == 'D') {
          data.level = 1;
        } else {
          data.level = 1;
        }

        // Find the user's contract data
        let contract_data = await SmartContract.findOne({
          universal_id: user.contact,
        });

        if (contract_data) {
          // Remove sensitive information from the contract data
          contract_data.universal_id = undefined;
          contract_data.__v = undefined;
          contract_data._id = undefined;
          data.contract_data = contract_data;
