  UpdateUIDWithDOB: async (req, res) => {
    /*
        The code updates the UID of a user in the database. 
        It starts by finding a user with a matching contact number and then, 
         concatenates the first 6 characters of the UID, the date of birth, and the last 5 characters of the UID to create a new UID. 
         Then it updates the user document with the new UID. 
         If the update is successful, the updated user document is returned, otherwise an error message is returned.
        */
    try {
      // Destructure the request body to get the contact, _id, and dob
      const { dob, contact, _id } = req.body;

      // Validate that all required fields are present
      if (!_id || !contact || !dob) {
        return res.status(httpStatus.BAD_REQUEST).json({
          success: false,
          message: 'Missing required parameters: _id, contact, and dob are required.',
        });
      }

      // Find user with matching contact number
      let existedUser = await User.findOne({ contact: contact });

      if (existedUser) {
        uid = existedUser.UID;
        // Concatenate the first 6 characters of the UID, the date of birth, and the last 5 characters of the UID
        existedUser.UID = `${uid.slice(0, 6)}${dob}${uid.slice(-5)}`;

        // Update the user document
        await existedUser.updateOne();

        // Retrieve the updated user
        existedUser = await User.findOne({ UID: existedUser.UID });
        // Remove sensitive information from the contract data
        existedUser.password = undefined;
        existedUser.salt = undefined;
        existedUser.__v = undefined;

        return res.status(httpStatus.OK).json({
          success: true,
          message: 'User UID updated successfully',
          data: existedUser,
        });
      }
    } catch (error) {
      console.log({
        api: 'Update UID Fialure',
        method: req.method,
        route: req.originalUrl,
        //File_Path : "Controllers/cashflow.controller.js",
        error: error.message,
      });
      return res.status(httpStatus.EXPECTATION_FAILED).json({
        success: false,
        error: error.message,
      });
    }
  },

