  // Function to handle changing of password for a user
  changePassword: async (req, res) => {
    // The function takes in the required fields contact, _id, prevPassword, and newPassword from the request body.

    // The function first checks if the required fields are present, if not, it returns a 400 Bad Request response.

    // It then searches for the user with the given contact number. If the user is not found, it returns a 400 Bad Request response.

    // If the provided prevPassword does not match the user's current password, it returns a 400 Bad Request response.

    // If the new password is the same as the previous password, it returns a 400 Bad Request response.

    // If everything is in order, the user's password is updated to the new password and a success response is returned.

    // In case of any error, the error message is logged and a 417 Expectation Failed response is returned.

    try {
      // Destructure the required fields from request body
      const { contact, _id, prevPassword, newPassword } = req.body;

      // Check if required fields are present in the request body
      if (!contact || !_id || !prevPassword || !newPassword) {
        return res.status(httpStatus.BAD_REQUEST).json({
          success: false,
          message: 'Bad request, please provide all required fields',
        });
      }

      // Find the user with the provided contact number
      const user = await User.findOne({ contact: contact });
      if (!user) {
        return res.status(httpStatus.BAD_REQUEST).json({
          success: false,
          message: 'No user found with provided contact number',
        });
      }

      // Check if the provided current password is correct
      if (!user.validPassword(prevPassword)) {
        return res.status(httpStatus.BAD_REQUEST).json({
          success: false,
          message: 'Wrong current password',
        });
      }

      // Check if new password is not same as previous password
      if (prevPassword === newPassword) {
        return res.status(httpStatus.BAD_REQUEST).json({
          success: false,
          message: 'New password can not be same as previous password',
        });
      }

      // Update the password for the user
      user.setPassword(newPassword);
      await user.updateOne({ password: user.password });

      // Return success response
      return res.status(httpStatus.OK).json({
        success: true,
        message: 'Password updated successfully',
      });
    } catch (error) {
      // Log the error
      console.log({
        api: 'Change Password',
        method: req.method,
        route: req.originalUrl,
        error: error.message,
      });

      // Return error response
      return res.status(httpStatus.EXPECTATION_FAILED).json({
        success: false,
        error: error.message,
      });
    }
  },

