  // Function to get balances of all the accounts associated with a contact
  getBalances: async (req, res) => {
    try {
      // Extracting the contact and _id from the request body
      const { contact, _id } = req.body;
      // Extracting the token from the query parameters
      const { token } = req.query;

      //console.log({token, body : req.body});

      // Check if contact, _id and token are present or not
      if (!contact || !_id || !token) {
        // Return a BAD REQUEST response if any of them is missing
        return res.status(httpStatus.BAD_REQUEST).json({
          success: false,
          message: 'Bad Request: Missing contact, _id, or token.',
        });
      }
      let country = await User.findOne({ contact: contact }, { country: 1 });
      //console.log(country);
      if (!country) {
        country = await pendinguserModel.findOne({ contact: contact }, { country: 1 });
      }

      const [currency, accounts] = await Promise.all([
        Country.findOne(
          { code: country.country },
          {
            currency_symbol: 1,
            icon: 1,
            currency_sign: 1,
          }
        ),
        Account.find({ contact }),
      ]);
      //console.log(currency, accounts);
      let exchange_rates = await getExchangeRates(currency.currency_symbol);

      // Fetch all the accounts associated with the contact

      // Check if any account is found for the contact
      if (!accounts.length) {
        // Return a NOT FOUND response if no account is found
        return res.status(httpStatus.OK).json({
          success: true,
          message: 'No accounts found for this user.',
          data: [],
        });
      }

      const balances = await Promise.all(
        accounts.map(async (account) => {
          if (account.balance || account.balance == 0) {
            balance = [{ interimAvailable: {} }];
            balance[0].interimAvailable['amount'] = account.balance + '.00';
            balance[0].interimAvailable['currency'] = currency.currency_symbol;
            balance[0].interimAvailable['currency_symbol'] = currency.currency_sign;
            balance[0].interimAvailable['label'] = account.type;
            balance[0].interimAvailable['flag'] = currency.icon;
            balance[0].interimAvailable['exchange_rates'] = exchange_rates.exchange_rates[currency.currency_symbol];
            balance[0].interimAvailable['exchange_value'] = account.balance;
            return { [account.account]: balance };
          } else {
            const balance = await Balance(token, account.account, account.type ? account.type : 'Not Assigned');
            if (balance[0].interimAvailable) {
              balance[0].interimAvailable['exchange_rates'] =
                exchange_rates.exchange_rates[balance[0].interimAvailable.currency];
              balance[0].interimAvailable['exchange_value'] =
                parseFloat(balance[0].interimAvailable.amount) /
                parseFloat(exchange_rates.exchange_rates[balance[0].interimAvailable.currency]);
              //total_amount.interimAvailable += parseFloat(balance[0].interimAvailable.amount) / parseFloat(exchange_rates.rates[balance[0].interimAvailable.currency]);
            }
            if (balance[0].expected) {
              //console.log("YES");
              balance[0].expected['exchange_rates'] = exchange_rates.exchange_rates[balance[0].expected.currency];
              balance[0].expected['exchange_value'] =
                parseFloat(balance[0].expected.amount) /
                parseFloat(exchange_rates.exchange_rates[balance[0].expected.currency]);
              //total_amount.expected += (parseFloat(balance[0].expected.amount)/ parseFloat(exchange_rates.rates[balance[0].expected.currency]));
            }
            //return balance[0];
            return { [account.account]: balance };
          }
        })
      );

      // Return a success response with the balances
      return res.status(httpStatus.OK).json({
        success: true,
        message: 'Balances retrieved successfully.',
        data: Object.assign({}, ...balances),
      });
    } catch (error) {
      // Log the error in case of any failure

      console.error({
        api: 'Get Balances',
        method: req.method,
        route: req.originalUrl,
        error: error,
      });

      // Return an INTERNAL SERVER ERROR response in case of failure
      return res.status(httpStatus.INTERNAL_SERVER_ERROR).json({
        success: false,
        message: 'Failed to retrieve balances.',
        error: error.message,
      });
    }
  },

