              exchange_rates.exchange_rates[balance[0].interimAvailable.currency];
            balance[0].interimAvailable['exchange_value'] =
              parseFloat(balance[0].interimAvailable.amount) /
              parseFloat(exchange_rates.exchange_rates[balance[0].interimAvailable.currency]);
            total_amount.interimAvailable +=
              parseFloat(balance[0].interimAvailable.amount) /
              parseFloat(exchange_rates.exchange_rates[balance[0].interimAvailable.currency]);
          }
          if (balance[0].expected) {
            //console.log("YES");
