      if (newAccount == 'true') {
        uniqueAccounts = uniqueAccounts.filter((acc) => acc.account_type === 'Not Assigned');
      }

      // Return the response in JSON format with success status
      return res.status(httpStatus.OK).json({
        success: true,
        message: 'Success',
