  getCategorizedData: async (req, res) => {
    const body = req.body;
    FetchTransaction(body, (err, result) => {
      if (err) {
        return res.status(404).json({
          success: false,
          message: err.toString(),
        });
      }

      if (!result) {
        return res.status(500).json({
          success: false,
          message: 'Some Technical Issue Occured While Creating user',
        });
      }
      transactions = JSON.parse(result.toString()).transactions;
      booked = transactions.booked;
      categorized_data = {};
      console.log(booked.length);
      if (booked.length == 0) {
        return res.status(404).json({
          success: false,
          message: 'No transaction found fo the account in last 3 months',
        });
      }
      for (const transaction of booked) {
        const transaction_amount = transaction.transactionAmount;
        const transaction_category = transaction.categorisation;
        if (categorized_data[transaction_category.categoryId]) {
          categorized_data[transaction_category.categoryId] = {
