  AddJob: async (req, res) => {
    const body = req.body;
    const new_job = {
      job_name: body.job_name,
      amount: body.amount,
      income_date: body.income_date,
      income_frequency: body.income_frequency,
    };
    console.log(req.body);
    getJobs(body.contact, (err, job) => {
      if (err) {
        return res.status(404).json({
          success: false,
          message: err.toString(),
        });
      }
      if (!job) {
        return res.status(403).json({
          success: false,
          message: 'Server Error',
        });
      }
      //console.log("job" + job.toString());
      const jobs_array = job.jobs;
      let job_alread = false;
      jobs_array.forEach((job) => {
        if (JSON.stringify(job) == JSON.stringify(new_job)) {
          job_alread = true;
        }
      });
      if (!job_alread) {
        const current_jobs = job.jobs;
        current_jobs.push(new_job);
        body.current_jobs = current_jobs;
        updateJobs(body, (err, results) => {
          if (err)
            return res.status(404).json({
              success: false,
              message: err.toString(),
            });
          if (!results)
            return res.status(403).json({
              success: false,
              message: 'Can not Update Job at the moment',
            });
          return res.status(200).json({
            success: true,
            message: 'success',
            data: results,
          });
        });
      } else {
        res.status(402).json({
          success: false,
          message: 'Job already Exists',
        });
      }
    });
  },

