  updateCategoryAccount: async (req, res) => {
    var body = req.body;
    findCategoryAcccountByID(body, (err, result) => {
      if (err) {
        return res.status(404).json({
          success: false,
          message: err.toString(),
        });
      }
      if (!result) {
        return res.status(403).json({
          success: false,
          message: 'Data you want to update does not exist',
        });
      }
      body.doc_id = result._id;
      updateCategoryAccount(body, (err, category) => {
        if (err) {
          return res.status(404).json({
            success: false,
            message: err.toString(),
          });
        }
        if (!result) {
          return res.status(404).json({
            success: false,
            message: "Data can't be stored at the moment.",
          });
        }
        category.contact = undefined;
        category.__v = undefined;

        var response_body = {};

        response_body.id = category.id;
        response_body.name = category.name;
        response_body.planned = 0;
        response_body.spent = 0;
        if (category.is_category == 'true') {
          var data = {};
          data.category_id = category.id;

          getAllSubCategories(data, (err, subcategories) => {
            if (err) {
              return res.status(404).json({
                success: false,
                message: err.toString(),
                data: response_body,
              });
            }
            if (subcategories.length == 0) {
              return res.status(404).json({
                success: false,
                message: 'No Sub categories exist for the Given Category',
              });
            }
            var subcategory_ids = [];

            subcategories.forEach((subcategory) => {
              subcategory_ids.push(subcategory.subcategory_id);
            });

            body.subcategory_ids = subcategory_ids;
            body.month = new Date().getMonth() + 1;
            body.year = new Date().getFullYear();

            getSubcategoriesBudgetForMonth(body, (err, results) => {
              if (err) {
                return res.status(404).json({
                  success: false,
                  message: err.toString(),
                  data: response_body,
                });
              }
              if (results.length == 0) {
                return res.status(404).json({
                  success: false,
                  message: 'No Budget exist for the Given Sub Category',
                  data: response_body,
                });
              }
              results.forEach((subcategory) => {
                response_body.planned += subcategory.planned;
              });

              body.from = new Date().getFullYear().toString() + '-' + ('0' + body.month).slice(-2) + '-01';
              body.to = new Date().getFullYear().toString() + '-' + ('0' + body.month).slice(-2) + '-31';

              getTransactionsBySubcategories(body, (err, transactions) => {
                if (err) {
                  return res.status(404).json({
                    success: false,
                    message: err.toString(),
                    data: response_body,
                  });
                }
                transactions.forEach((transaction) => {
                  response_body.spent += parseFloat(transaction.transactionAmount.amount);
                });
                return res.status(200).json({
                  success: true,
                  message: 'success',
                  data: response_body,
                });
              });
            });
          });
        } else {
          var data = {};
          data.subcategory_id = category.id;
          data.contact = body.contact;
          findSubcategoryBudget(data, (err, result) => {
            if (err) {
              return res.status(404).json({
                success: false,
                message: err.toString(),
                data: response_body,
              });
            }
            if (!result) {
              return res.status(404).json({
                success: false,
                message: 'No Budget exist for the Given Sub Category',
                data: response_body,
              });
            }
            response_body.planned += result.planned;
            body.month = new Date().getMonth() + 1;
            body.year = new Date().getFullYear();
            body.from = new Date().getFullYear().toString() + '-' + ('0' + body.month).slice(-2) + '-01';
            body.to = new Date().getFullYear().toString() + '-' + ('0' + body.month).slice(-2) + '-31';

            getTransactionsBySubCategory(body, (err, transactions) => {
              if (err) {
                return res.status(404).json({
                  success: false,
                  message: err.toString(),
                  data: response_body,
                });
              }
              transactions.forEach((transaction) => {
                response_body.spent += parseFloat(transaction.transactionAmount.amount);
              });
              return res.status(200).json({
                success: true,
                message: 'success',
                data: response_body,
              });
            });
          });
        }
      });
    });
  },

