  getTransactions: async (req, res) => {
    try {
      const { contact, _id } = req.body;
      let page_no = req.query.page_no;
      if (!contact || !_id || !page_no) {
        return res.status(httpStatus.BAD_REQUEST).json({
          success: false,
          message: 'Request with Insufficient Data',
        });
      }
      const total_pages = await Transaction.find({ contact: contact }).count();
      if (total_pages == 0) {
        return res.status(httpStatus.OK).json({
          success: true,
          message: 'No transaction available',
          current_page: current_page,
          data: [],
          first_page_url: 'https://api.universalflow.io/user/getuserTransactions?page_no=1',
          from: null,
          last_page: last_page,
          last_page_url: last_page_url,
          next_page_url: next_page_url,
          per_page: 50,
          prev_page_url: prev_page_url,
          to: null,
          total: total_pages,
        });
      }
      //console.log(total_pages, total_pages/50, Math.ceil(total_pages/50));
      let prev_page = null;
      let prev_page_url = null;
      let last_page = Math.ceil(total_pages / 50);
      let next_page = parseInt(page_no) > 1 ? parseInt(page_no) + 1 : 2;
      let current_page = 1;
      if (parseInt(page_no) > 1 && parseInt(page_no) < last_page) {
        current_page = parseInt(page_no);
      } else if (parseInt(page_no) < 1) {
        current_page = 1;
      } else {
        current_page = last_page;
      }
      let last_page_url = `https://api.universalflow.io/user/getuserTransactions?page_no=${last_page}`;
      let next_page_url = `https://api.universalflow.io/user/getuserTransactions?page_no=${next_page}`;
      if (parseInt(page_no) > 1 && parseInt(page_no) < last_page) {
        prev_page = parseInt(page_no) - 1;
        prev_page_url = `https://api.universalflow.io/user/getuserTransactions?page_no=${prev_page}`;
      }
      if (parseInt(page_no) > last_page) {
        prev_page = Math.ceil(total_pages / 50);
        prev_page_url = `https://api.universalflow.io/user/getuserTransactions?page_no=${prev_page}`;
      }
      if (next_page > Math.ceil(total_pages / 50)) {
        next_page = null;
        next_page_url = null;
      }
      if (last_page < parseInt(page_no)) {
        return res.status(httpStatus.BAD_REQUEST).json({
          success: false,
          message: `Page no can not be larger than ${Math.ceil(total_pages / 50)}`,
          current_page: current_page,
          data: [],
          first_page_url: 'https://api.universalflow.io/user/getuserTransactions?page_no=1',
          from: null,
          last_page: last_page,
          last_page_url: last_page_url,
          next_page_url: next_page_url,
          per_page: 50,
          prev_page_url: prev_page_url,
          to: null,
          total: total_pages,
        });
      }
      if (parseInt(page_no) < 0) {
        page_no = 1;
      }
      const tansactions = await Transaction.find({ contact: contact })
        .sort({
          transaction_date: -1,
        })
        .skip((page_no - 1) * 50)
        .limit(50);
      return res.status(200).json({
        success: true,
        message: 'success',
        current_page: parseInt(page_no),
        data: tansactions,
        first_page_url: 'https://api.universalflow.io/user/getuserTransactions?page_no=1',
        from: 50 * parseInt(page_no - 1) + 1,
        last_page: last_page,
        last_page_url: last_page_url,
        next_page_url: next_page_url,
        per_page: 50,
        prev_page_url: prev_page_url,
        to: last_page == parseInt(page_no) ? total_pages : 50 * parseInt(page_no),
        total: total_pages,
      });
    } catch (error) {
      console.log({
        api: 'Get Transaction API',
        method: req.method,
        route: req.originalUrl,
        //File_Path : "Controllers/cashflow.controller.js",
        error: error.message,
      });
      return res.status(httpStatus.EXPECTATION_FAILED).json({
        success: true,
        messge: 'Get Transaction API failed',
        error: error.message,
      });
    }
  },

  createTransactions: async (req, res) => {
    try {
      const { contact, _id, amount, subcategory_id, date, reason, account_id, currency } = req.body;
      if (!subcategory_id || !date || !reason) {
        return res.status(httpStatus.OK).json({ success: false, message: 'Bad Request' });
      }
      const code = await User.findOne({ contact: contact }, { country: 1 });
      let country_code = await Country.findOne({ code: code.country }, { currency_symbol: 1 });
      const subcategory = await SubCategory.find({ subcategory_id: subcategory_id }, { name: 1 });
      //console.log(country_code);
      const transaction = new Transaction({
        contact: contact,
        account_id: account_id,
        subcategory_information: [
          {
            subcategory_id: subcategory_id,
            subcategory_name: subcategory.name,
            amount: amount,
            currency: currency ? currency : country_code.currency_symbol,
            default: true,
          },
        ],
        transaction_date: date,
        remittanceInformationUnstructured: reason,
        transactionAmount: {
          amount: amount,
          currency: country_code.currency_symbol,
        },
        transactionId: randomstring.generate(),
        enrichment: {},
        manual: true,
      });
      await transaction.save();
      return res.status(httpStatus.OK).json({
        success: true,
        message: 'success',
        data: transaction,
      });
    } catch (error) {
      console.log({
        api: 'Add Manual Transaction API',
        method: req.method,
        route: req.originalUrl,
        //File_Path : "Controllers/cashflow.controller.js",
        error: error.message,
      });
      return res.status(httpStatus.EXPECTATION_FAILED).json({
        success: true,
        messge: 'Add Manual Transaction API',
        error: error.message,
      });
    }
  },

  searchtransactions: async (req, res) => {
    const { param } = req.query;
    const { contact, _id } = req.body;
    date = param.split('.');
    search_param = param;
    if (date.length > 1) {
      search_param = ('0' + date[1]).slice(-2) + '-' + ('0' + date[0]).slice(-2);
    }
    const transactions = await Transaction.aggregate([
      {
        $match: {
          contact: contact,
          $or: [
            {
              transaction_date: {
                $regex: search_param,
              },
            },
            {
              'transactionAmount.amount': {
                $regex: search_param,
              },
            },
            {
              creditorName: {
                $regex: search_param,
              },
            },
            {
              remittanceInformationUnstructured: {
                $regex: search_param,
              },
            },
            {
              'enrichment.displayName': {
                $regex: search_param,
                $options: 'i',
              },
            },
            {
              subcategory_information: {
                $elemMatch: {
                  name: {
                    $regex: search_param,
                    $options: 'i',
                  },
                },
              },
            },
          ],
        },
      },
      {
        $sort: {
          transaction_date: -1,
        },
      },
    ]);
    return res.status(httpStatus.OK).json({
      success: true,
      message: 'Search Transactions are .',
      data: transactions,
    });
  },

