  RemoveAccount: async (req, res) => {
    try {
      const { contact, _id, account_id } = req.body;

      if (!account_id) {
        return res.status(httpStatus.BAD_REQUEST).json({
          success: false,
          message: 'Missing required parameter: account_id is required.',
        });
      }

      const account = await Account.findOneAndDelete({
        contact: contact,
        account: account_id,
      });

      if (!account) {
        return res.status(httpStatus.NOT_FOUND).json({
          success: false,
          message: 'Account not found.',
        });
      }

      await Transaction.deleteMany({ account_id: account_id });

      return res.status(httpStatus.OK).json({
        success: true,
        message: 'Account and associated transactions have been removed successfully.',
      });
    } catch (error) {
      console.error({
        api: 'Remove Account',
        method: req.method,
        route: req.originalUrl,
        error: error.message,
      });

      return res.status(httpStatus.INTERNAL_SERVER_ERROR).json({
        success: false,
        error: 'An error occurred while removing the account.',
      });
    }
  },

