  deleteTransaction: async (req, res) => {
    const body = req.body;
    deleteTransactionData(body, (err, result) => {
      if (err) {
        return res.status(404).json({
          success: false,
          message: 'Delete Transaction Failed',
          err: err.toString(),
        });
      }
      if (result.status) {
        return res.status(409).json({
          success: false,
          message: result.status,
          data: result.data,
        });
      }
      return res.status(200).json({
        success: true,
        message: 'Manual Transaction deleted successfully',
        data: result,
      });
    });
  },

