  changeSubcategory2: async (req, res) => {
    try {
      const { contact, transactionid, current_subcategory_id, amount, new_subcategory_id, new_subcategory_name } =
        req.body;

      const transaction = await Transaction.findOne({
        transactionId: transactionid,
        contact: contact,
      });
      //console.log(transaction);
      let transaction_subcategories = transaction.subcategory_information;
      //let flag = false;

      transaction_subcategories[0].subcategory_id = new_subcategory_id;
      transaction_subcategories[0].name = new_subcategory_name;

      if (!transaction.remittanceInformationUnstructured) {
        //console.log({creditorName : transaction['creditorName'], loanorName : transaction['loanorName']})
        await transaction.updateOne({
          subcategory_information: transaction_subcategories,
        });
        return res.status(httpStatus.OK).json({
          success: true,
          message: 'Can not Find Similar Transactions due to lack of data',
          similar_transactions: [],
        });
      }

      let global_consensus = await globalConsensus.findOne({
        merchant_name: transaction.remittanceInformationUnstructured,
      });
      let local_consensus = await localConsensus.findOne({
        contact: contact,
        merchant_name: transaction.remittanceInformationUnstructured,
      });
      //console.log({contact : contact , $or : [{merchant_name : transaction.creditorName}, {merchant_name : transaction.debitorName}]})
      //console.log(local_consensus);
      if (local_consensus) {
        let consensus = local_consensus.consensus;
        if (consensus[current_subcategory_id]) {
          consensus[current_subcategory_id] = parseInt(consensus[current_subcategory_id].count) - 1;
        }

        consensus[new_subcategory_id] = {
          count: consensus[new_subcategory_id] ? parseInt(consensus[new_subcategory_id].count) + 1 : 1,
          name: new_subcategory_name,
        };
        await local_consensus.updateOne({ consensus: consensus });
      } else {
        let consensus = {};
        consensus[new_subcategory_id] = {
          count: 1,
          name: new_subcategory_name,
        };

        const new_local_consensus = new localConsensus({
          contact: contact,
          merchant_name: transaction.remittanceInformationUnstructured,
          consensus: consensus,
        });

        await new_local_consensus.save();
      }
      if (global_consensus) {
        let glConsensus = global_consensus.consensus;
        if (glConsensus[current_subcategory_id]) {
          glConsensus[current_subcategory_id].count = parseInt(glConsensus[current_subcategory_id].count) - 1;
        }
        glConsensus[new_subcategory_id] = {
          count: glConsensus[new_subcategory_id] ? parseInt(glConsensus[new_subcategory_id].count) + 1 : 1,
          name: new_subcategory_name,
        };
        await global_consensus.updateOne({ consensus: glConsensus });
      } else {
        let glConsensus = {};
        glConsensus[new_subcategory_id] = {
          count: 1,
          name: new_subcategory_name,
        };
        const new_global_consensus = new globalConsensus({
          merchant_name: transaction.remittanceInformationUnstructuredArray.toString(),
          consensus: glConsensus,
        });

        await new_global_consensus.save();
      }

      let merchant_name = transaction.remittanceInformationUnstructured;

      //let amount = transaction.transactionAmount.amount
      let updatable_transactions = await Transaction.aggregate([
        {
          $match: {
            $and: [
              { contact: contact },
              {
                remittanceInformationUnstructured: merchant_name,
              },

              { transactionId: { $ne: transactionid } },
            ],
          },
        },
        {
          $addFields: {
            // Check if subcategory_id contains '13'
            containsSubcategory13: {
              $anyElementTrue: [
                {
                  $map: {
                    input: '$subcategory_information',
                    as: 'item',
                    in: {
                      $regexMatch: {
                        input: '$$item.subcategory_id',
                        regex: /13/,
                      },
                    },
                  },
                },
              ],
            },
          },
        },
        {
          $sort: {
            containsSubcategory13: -1, // sort by subcategory 13 first
            transaction_date: 1, // then sort by transaction_date
          },
        },
      ]);
      let flag = true;
      if (flag) {
        await transaction.updateOne({
          subcategory_information: transaction_subcategories,
        });
        data = await Transaction.findOne({
          contact: contact,
          transactionId: transactionid,
        });

        return res.status(httpStatus.OK).json({
          success: true,
          message: 'Transaction updated successfully',
          data: data,
          similar_transactions: updatable_transactions,
        });
      }
      return res.status(httpStatus.BAD_REQUEST).json({
        success: true,
        message: 'provided subcategory_id does not exist',
        data: data,
        similar_transactions: updatable_transactions,
      });
    } catch (error) {
      console.log({
        api: 'Subcategory information change',
        method: req.method,
        route: req.originalUrl,
        error: error.message,
      });
      res.status(httpStatus.INTERNAL_SERVER_ERROR).json({
        success: false,
        message: error.message,
      });
    }
  },

