  updatesubcategoryTransaction: async (req, res) => {
    try {
      const { contact, name, transactionId, subcategory_id, amount, new_amount } = req.body;
      const transction = await Transaction.findOne({
        transactionId: transactionId,
        contact: contact,
      });
      if (!transction) {
        return res.status(httpStatus.BAD_REQUEST).json({
          success: false,
          message: 'No transaction found',
          data: [],
        });
      }
      transaction_subcategories = transction.subcategory_information;
      for (let subcategory of transaction_subcategories) {
        if (subcategory.subcategory_id == subcategory_id && subcategory.default != true) {
          subcategory.amount = -new_amount;
          transaction_subcategories[0].amount -= 0 - new_amount - subcategory.amount;
        }
      }
      await transction.updateOne({
        subcategory_information: transaction_subcategories,
      });
      const updated_transaction = await Transaction.findOne({
        contact: contact,
        transactionId: transactionId,
      });
      return res.status(httpStatus.OK).json({
        success: true,
        message: 'updated transaction',
        data: updated_transaction,
      });
    } catch (error) {
      console.log({
        api: 'Update Transaction Subcategory',
        method: req.method,
        route: req.originalUrl,
        //File_Path : "Controllers/cashflow.controller.js",
        error: error.message,
      });
      return res.status(httpStatus.EXPECTATION_FAILED).json({
        success: true,
        messge: 'Update Transaction Subcategory',
        error: error.message,
      });
    }
  },

