const axios = require('axios');

require('dotenv').config({ path: './config/config.env' });

const AUTH_RPC_URL = process.env.AUTH_RPC_URL || 'http://localhost:4001/rpc/auth/verify';
const AUTH_RPC_TIMEOUT_MS = Number(process.env.AUTH_RPC_TIMEOUT_MS || 3000);

/**
 * Verifies a JWT token via external auth RPC service.
 * Expected success response shape (flexible):
 * {
 *   success: true,
 *   data: { _id, contact, ... }
 * }
 */
async function verifyToken(token) {
  if (!token) {
    return {
      success: false,
      code: 'NO_TOKEN',
      message: 'Access Denied! No token provided.',
    };
  }

  try {
    const response = await axios.post(
      AUTH_RPC_URL,
      { token },
      {
        timeout: AUTH_RPC_TIMEOUT_MS,
        headers: { 'Content-Type': 'application/json' },
      }
    );

    const payload = response && response.data ? response.data : {};

    if (payload.success === false) {
      return {
        success: false,
        code: payload.code || 'INVALID_TOKEN',
        message: payload.message || 'Invalid token',
      };
    }

    const user = payload.data || payload.user || payload.decoded || payload;

    if (!user || !user._id || !user.contact) {
      return {
        success: false,
        code: 'INVALID_PAYLOAD',
        message: 'Invalid token payload.',
      };
    }

    return {
      success: true,
      user: {
        _id: String(user._id),
        contact: String(user.contact),
      },
    };
  } catch (error) {
    // Upstream auth service/network issue
    if (error.code === 'ECONNABORTED') {
      return {
        success: false,
        code: 'AUTH_RPC_TIMEOUT',
        message: 'Authentication service timeout.',
      };
    }

    if (error.response && error.response.data) {
      const data = error.response.data;
      return {
        success: false,
        code: data.code || 'AUTH_RPC_ERROR',
        message: data.message || 'Authentication service rejected token.',
      };
    }

    return {
      success: false,
      code: 'AUTH_RPC_UNAVAILABLE',
      message: 'Authentication service unavailable.',
    };
  }
}

module.exports = {
  verifyToken,
};

