require('dotenv').config({ path: './config/config.env' });

module.exports = {
  checkToken: async (req, res, next) => {
    try {
      const authorizationHeader = req.get('authorization');

      if (!authorizationHeader) {
        return res.status(401).json({
          success: false,
          message: 'Access Denied! No token provided.',
        });
      }

      // Handle both "Bearer TOKEN" and raw token formats
      const token = authorizationHeader.split(' ')[1] || authorizationHeader;

      const verification = await verifyToken(token);

      if (!verification.success) {
        if (verification.code === 'TOKEN_EXPIRED') {
          return res.status(401).json({
            success: false,
            message: 'Token has expired. Please login again.',
          });
        }

        // Preserve existing 401 semantics for invalid auth
        return res.status(401).json({
          success: false,
          message: verification.message || 'Invalid Token',
        });
      }

      req.user = {
        _id: verification.user._id,
        contact: verification.user.contact,
      };

      req.body._id = verification.user._id;
      req.body.contact = verification.user.contact;

      return next();
    } catch (error) {
      console.error('Token validation error:', error);
      return res.status(500).json({
        success: false,
        message: 'Authentication error: ' + error.message,
      });
    }
  },
};

